const source=$('Preparar contexto sanitizado').item.json;
let generated=$json.output??$json;
if(typeof generated==='string'){
  try{generated=JSON.parse(generated);}
  catch{throw new Error('A IA não retornou JSON válido.');}
}
const stripFence=value=>String(value??'').trim()
  .replace(/^```(?:mermaid)?\s*/i,'')
  .replace(/\s*```$/,'')
  .trim();
const readmeMarkdown=stripFence(generated.readmeMarkdown);
const architectureMermaid=stripFence(generated.architectureMermaid);
if(!readmeMarkdown.startsWith('# ')) throw new Error('README gerado pela IA precisa começar com um título H1.');
if(!/^(flowchart|graph)\s+(TD|TB|BT|RL|LR)\b/i.test(architectureMermaid)){
  throw new Error('architecture.mmd gerado pela IA não contém um grafo Mermaid válido.');
}
const architectureSection=[
  '## Arquitetura','',
  '```mermaid',architectureMermaid,'```','',
  '[Abrir a fonte do diagrama](docs/architecture.mmd)'
].join('\n');
const readmeWithArchitecture=readmeMarkdown.trim()+'\n\n'+architectureSection;
const reviewNotes=Array.isArray(generated.reviewNotes)?generated.reviewNotes.map(String).filter(Boolean):[];
const confidence=['low','medium','high'].includes(generated.confidence)?generated.confidence:'low';
const {aiPrompt,...base}=source;
return {json:{
  ...base,
  humanFiles:{
    'README.md':readmeWithArchitecture+'\n',
    'docs/architecture.mmd':architectureMermaid+'\n'
  },
  aiDocumentation:{reviewNotes,confidence},
  reviewRequired:true
}};

const payloads = $input.all().map(item => item.json);
if (payloads.length === 0) throw new Error("Nenhum enriquecimento foi gerado.");
return [{ json: {
  status: "ai-enriched",
  enrichedProjects: payloads.length,
  payloads,
  reviewRequired: true,
  generatedAt: new Date().toISOString()
}}];
